extends SceneTree

func _init() -> void:
	# (a) namespaced subject and counter composition, non-negative mask, posmod
	var step_no: int = 123456
	var subj_node: int = (0 << 18) | 5
	var subj_edge: int = (1 << 18) | 5
	var c1: int = (step_no << 20) | subj_node
	var c2: int = (step_no << 20) | subj_edge
	print("counters differ: ", c1 != c2, " ", c1, " ", c2)
	var raw: int = -7046029254386353131
	var masked: int = raw & 0x7FFFFFFFFFFFFFFF
	print("masked nonneg: ", masked >= 0, " posmod1000=", posmod(masked, 1000), " int type=", typeof(masked))
	var raw2: int = -1
	print("mask of -1 = ", raw2 & 0x7FFFFFFFFFFFFFFF)
	# (b) insertion sort of N packed keys (key<<8 | arrival)
	for n in [16, 56, 64]:
		var keys := PackedInt64Array()
		keys.resize(n)
		var seed: int = 12345
		var t0: int = Time.get_ticks_usec()
		var reps: int = 2000
		for r in reps:
			for i in n:
				seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
				keys[i] = ((seed % 4096) << 8) | i
			for i in range(1, n):
				var v: int = keys[i]
				var j: int = i - 1
				while j >= 0 and keys[j] > v:
					keys[j + 1] = keys[j]
					j -= 1
				keys[j + 1] = v
		var dt: float = float(Time.get_ticks_usec() - t0) / float(reps)
		print("insertion sort n=", n, " us/iter (incl. fill) = ", dt)
	# (c) direct loop vs active-list indirection, 4096 elements, read-modify-write
	var col := PackedInt64Array()
	col.resize(4096)
	var lst := PackedInt32Array()
	lst.resize(4096)
	for i in 4096:
		lst[i] = i
		col[i] = i * 3
	var reps2: int = 200
	var t1: int = Time.get_ticks_usec()
	for r in reps2:
		for i in 4096:
			col[i] = col[i] + 1
	var d_direct: float = float(Time.get_ticks_usec() - t1) / float(reps2)
	var t2: int = Time.get_ticks_usec()
	for r in reps2:
		for k in 4096:
			var i2: int = lst[k]
			col[i2] = col[i2] + 1
	var d_ind: float = float(Time.get_ticks_usec() - t2) / float(reps2)
	print("direct us/4096=", d_direct, " indirect us/4096=", d_ind)
	# (d) delta accumulate + apply vs next-array copy+swap for 4096
	var acc := PackedInt64Array()
	acc.resize(4096)
	var t3: int = Time.get_ticks_usec()
	for r in reps2:
		for i in 4096:
			acc[i] = (i & 7) - 3
		for i in 4096:
			col[i] += acc[i]
			acc[i] = 0
	var d_acc: float = float(Time.get_ticks_usec() - t3) / float(reps2)
	var nxt := PackedInt64Array()
	nxt.resize(4096)
	var t4: int = Time.get_ticks_usec()
	for r in reps2:
		nxt = col.duplicate()
		for i in 4096:
			nxt[i] = col[i] + ((i & 7) - 3)
		var tmp: PackedInt64Array = col
		col = nxt
		nxt = tmp
	var d_swap: float = float(Time.get_ticks_usec() - t4) / float(reps2)
	print("delta-accumulate+apply us/4096=", d_acc, " copy+next+swap us/4096=", d_swap)
	# (e) mini/maxi/clampi cost in loop
	var t5: int = Time.get_ticks_usec()
	for r in reps2:
		for i in 4096:
			col[i] = clampi(col[i], 0, 100000)
	print("clampi us/4096=", float(Time.get_ticks_usec() - t5) / float(reps2))
	quit()
EOF
